import{_ as e,o,c as d,ag as r}from"./chunks/framework.8tqBsFWt.js";const _=JSON.parse('{"title":"Time Off / PTO Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/pto.md","filePath":"reference/tools/pto.md"}'),a={name:"reference/tools/pto.md"};function s(n,t,i,c,l,p){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="time-off-pto-tools" tabindex="-1">Time Off / PTO Tools <a class="header-anchor" href="#time-off-pto-tools" aria-label="Permalink to &quot;Time Off / PTO Tools&quot;">​</a></h1><p>See <a href="/reference/workflows/time-off.html">Time Off Requests workflow</a> for the full step-by-step process.</p><hr><h2 id="setup_protected_projects" tabindex="-1">setup_protected_projects <a class="header-anchor" href="#setup_protected_projects" aria-label="Permalink to &quot;setup_protected_projects {#setup_protected_projects}&quot;">​</a></h2><p>Create (or verify) the protected internal PTO, Sick, and Leave projects for the tenant. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>02. Projects</code> (creates any of PTO, Sick, Leave that don&#39;t already exist)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><p>Idempotent — safe to call again; existing protected projects are left untouched. Run once during tenant onboarding, before any time off tool is used — every time off tool errors if its project hasn&#39;t been created yet.</p><hr><h2 id="request_time_off" tabindex="-1">request_time_off <a class="header-anchor" href="#request_time_off" aria-label="Permalink to &quot;request_time_off {#request_time_off}&quot;">​</a></h2><p>Submit a time off request. Creates a pending record and DMs all Managers and Owners. Time is <strong>not</strong> logged until approved.</p><p><strong>Writes to</strong>: <code>10. Pending_PTO</code>, <code>11. Unresolved_Items</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td>Must be the user making the request — self only</td></tr><tr><td><code>date</code></td><td>✅</td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>time_off_type</code></td><td>✅</td><td><code>&quot;PTO&quot;</code> | <code>&quot;Sick&quot;</code> | <code>&quot;Leave&quot;</code></td></tr><tr><td><code>hours</code></td><td></td><td>Defaults to tenant&#39;s hours-per-day (usually 8)</td></tr><tr><td><code>notes</code></td><td></td><td>Reason for the request</td></tr></tbody></table><p><strong>Response</strong>: &quot;Your PTO request for March 20 has been submitted. Your manager has been notified and will confirm.&quot;</p><blockquote><p>Use <code>request_time_off</code> — not <code>request_pto</code> — for all new time off requests.</p></blockquote><hr><h2 id="request_pto" tabindex="-1">request_pto <a class="header-anchor" href="#request_pto" aria-label="Permalink to &quot;request_pto {#request_pto}&quot;">​</a></h2><p>Submit a PTO request directly (used by the console self-service <code>/console/my-time-off</code> page). Creates a pending record and DMs all Managers and Owners. Time is <strong>not</strong> logged until approved.</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td>Must be the user making the request — self only</td></tr><tr><td><code>date</code></td><td>✅</td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>hours</code></td><td></td><td>Hours to request. When omitted or blank, defaults to the tenant&#39;s standard working-day length (<code>work_week.hours_per_day</code>, default 8)</td></tr><tr><td><code>notes</code></td><td></td><td>Reason for the request</td></tr></tbody></table><p><strong>Response</strong>: <code>{ success: true, request_id, date, hours, status: &quot;pending&quot; }</code></p><hr><h2 id="approve_time_off" tabindex="-1">approve_time_off <a class="header-anchor" href="#approve_time_off" aria-label="Permalink to &quot;approve_time_off {#approve_time_off}&quot;">​</a></h2><p>Approve a pending time off request. Logs the time entry and notifies the user via DM. <strong>Manager/Owner only.</strong></p><p><strong>Updates</strong>: <code>10. Pending_PTO</code> (status → <code>&quot;approved&quot;</code>) <strong>Writes to</strong>: <code>01. Time Entries</code> (logs hours to Out of Office project)</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>request_id</code></td><td>✅</td><td>The pending PTO record ID</td></tr></tbody></table><hr><h2 id="get_my_time_off" tabindex="-1">get_my_time_off <a class="header-anchor" href="#get_my_time_off" aria-label="Permalink to &quot;get_my_time_off {#get_my_time_off}&quot;">​</a></h2><p>View own time off history (pending, approved, rejected).</p><p><strong>Reads from</strong>: <code>10. Pending_PTO</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>time_off_type</code></td><td>Optional filter: <code>&quot;PTO&quot;</code> | <code>&quot;Sick&quot;</code> | <code>&quot;Leave&quot;</code></td></tr><tr><td><code>start_date</code></td><td>Optional range filter</td></tr><tr><td><code>end_date</code></td><td>Optional range filter</td></tr></tbody></table><hr><h2 id="get_team_time_off" tabindex="-1">get_team_time_off <a class="header-anchor" href="#get_team_time_off" aria-label="Permalink to &quot;get_team_time_off {#get_team_time_off}&quot;">​</a></h2><p>View team-wide Out of Office history across all users. <strong>Owner only.</strong></p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>03. Users</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>user_id</code></td><td>Optional — filter to one user by internal ID</td></tr><tr><td><code>time_off_type</code></td><td>Optional filter: <code>&quot;PTO&quot;</code> | <code>&quot;Sick&quot;</code> | <code>&quot;Leave&quot;</code></td></tr><tr><td><code>start_date</code></td><td>Optional range filter</td></tr><tr><td><code>end_date</code></td><td>Optional range filter</td></tr></tbody></table><p>Each entry includes <code>user_name</code> so the Owner can see who took what time off.</p><hr><h2 id="list_pending_pto" tabindex="-1">list_pending_pto <a class="header-anchor" href="#list_pending_pto" aria-label="Permalink to &quot;list_pending_pto {#list_pending_pto}&quot;">​</a></h2><p>All unresolved time off requests. <strong>Manager/Owner only.</strong></p><p><strong>Reads from</strong>: <code>10. Pending_PTO</code>, <code>03. Users</code></p><p>Managers see requests for users on their projects. Owners see all.</p><hr><h2 id="log_sick_day" tabindex="-1">log_sick_day <a class="header-anchor" href="#log_sick_day" aria-label="Permalink to &quot;log_sick_day {#log_sick_day}&quot;">​</a></h2><p>Log a sick day directly for a user. Does not require the request/approval flow. <strong>Manager/Owner only</strong> (Managers cannot log for themselves — only Owners can).</p><p><strong>Writes to</strong>: <code>01. Time Entries</code>, <code>11. Unresolved_Items</code> (flags conflict if user had active allocations that day)</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>user_name</code> or <code>slack_user_id</code></td><td>✅</td><td></td></tr><tr><td><code>date</code></td><td></td><td>Defaults to today</td></tr><tr><td><code>hours</code></td><td></td><td>Defaults to 8</td></tr></tbody></table><p><strong>Use case</strong>: When a team member is unexpectedly sick, a Manager can log it directly without a pending/approval cycle.</p><hr><h2 id="log_leave" tabindex="-1">log_leave <a class="header-anchor" href="#log_leave" aria-label="Permalink to &quot;log_leave {#log_leave}&quot;">​</a></h2><p>Log leave (unpaid or extended) for a user over a date range. Automatically skips weekends and company holidays. <strong>Manager/Owner only.</strong></p><p><strong>Writes to</strong>: <code>01. Time Entries</code> (one entry per working day), <code>11. Unresolved_Items</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>user_name</code> or <code>slack_user_id</code></td><td>✅</td><td></td></tr><tr><td><code>start_date</code></td><td>✅</td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>end_date</code></td><td>✅</td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>hours_per_day</code></td><td></td><td>Defaults to 8</td></tr><tr><td><code>notes</code></td><td></td><td></td></tr></tbody></table><hr><h2 id="set_pto_notice" tabindex="-1">set_pto_notice <a class="header-anchor" href="#set_pto_notice" aria-label="Permalink to &quot;set_pto_notice {#set_pto_notice}&quot;">​</a></h2><p>Set the tenant&#39;s minimum PTO notice period, in weeks. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: tenant config (<code>minimum_pto_notice_weeks</code>)</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>minimum_pto_notice_weeks</code></td><td>✅</td><td>Whole number, <code>0</code>–<code>52</code></td></tr></tbody></table><hr><h2 id="unresolved-items-from-time-off" tabindex="-1">Unresolved items from time off <a class="header-anchor" href="#unresolved-items-from-time-off" aria-label="Permalink to &quot;Unresolved items from time off&quot;">​</a></h2><p>When a sick day or leave is logged, VERA automatically checks if the user had active allocations on the affected dates. If so, it creates an Unresolved Item flagging the conflict:</p><ul><li><code>sick_conflict</code> — user is sick on a day with active allocations</li><li><code>leave_conflict</code> — leave logged over dates with active allocations</li><li><code>pto_conflict</code> — PTO approved for a date with active allocations</li></ul><p>Managers are shown these conflicts in morning summaries as 🔴 blocks and can resolve or dismiss them via <code>resolve_item</code> / <code>dismiss_item</code>.</p>',72)])])}const u=e(a,[["render",s]]);export{_ as __pageData,u as default};
